class Solution {
    public int minSetSize(int[] arr){
        Map<Integer,Integer> frequency=new HashMap<>();
        for(int value:arr)frequency.merge(value,1,Integer::sum);
        List<Integer> counts=new ArrayList<>(frequency.values());
        counts.sort(Collections.reverseOrder());
        int removed=0,answer=0;
        for(int count:counts){
            removed+=count;
            answer++;
            if(removed*2>=arr.length)break;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minSetSize(arr:IntArray):Int{
        val frequency=mutableMapOf<Int,Int>();
        for(value in arr)frequency[value]=(frequency[value]?:0)+1;
        var removed=0;
        var answer=0;
        for(count in frequency.values.sortedDescending()){
            removed+=count;
            answer++;
            if(removed*2>=arr.size)break
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int minSetSize(vector<int>& arr){
        unordered_map<int,int> frequency;
        for(int value:arr)++frequency[value];
        vector<int> counts;
        for(auto [value,count]:frequency)counts.push_back(count);
        sort(counts.rbegin(),counts.rend());
        int removed=0,answer=0;
        for(int count:counts){
            removed+=count;
            ++answer;
            if(removed*2>=(int)arr.size())break;
        }
        return answer;
    }
};
